import {
  Engine,
  Animation,
  AbstractMesh,
  ArcRotateCamera,
  Color4,
  Vector3,
  HemisphericLight,
  Scene,
  Tools,
  SceneLoader,
} from "@babylonjs/core";
import "@babylonjs/loaders/glTF";
import { BabylonjsProps } from "babylonjs-hook";

let scene: Scene;
let offscreenCanvas: OffscreenCanvas;
let camera: ArcRotateCamera;
let model: AbstractMesh;

// ZOOM animation
const getZoomAnimation = (duration: number) => {
  const frameRate = 20;
  const lastZoomFrame = duration * frameRate;

  const zoom = new Animation(
    "zoom",
    "position",
    20,
    Animation.ANIMATIONTYPE_VECTOR3,
    Animation.ANIMATIONLOOPMODE_CONSTANT
  );
  zoom.setKeys([
    { frame: 0, value: new Vector3(0, 70, 0) },
    { frame: lastZoomFrame, value: new Vector3(3, 7, -15) },
  ]);

  return {
    zoomAnimation: [zoom],
    lastZoomFrame,
  };
};

// SPIN animation
const getSpinAnimation = (rotationSpeed: number = 0.5) => {
  const spin = new Animation(
    "spinAnimation",
    "rotation",
    60,
    Animation.ANIMATIONTYPE_VECTOR3,
    Animation.ANIMATIONLOOPMODE_RELATIVE
  );
  const spinSpeed = model.rotation.y + rotationSpeed;
  spin.setKeys([
    { frame: 0, value: model.rotation },
    { frame: 60, value: new Vector3(0, spinSpeed, 0) },
  ]);

  return spin;
};

// SCENE READY handler
const onSceneReady = async (scene: Scene) => {
  try {
    // transparent background
    scene.clearColor = Color4.FromHexString("#000");

    // camera creation
    camera = new ArcRotateCamera(
      "camera1",
      Tools.ToRadians(0),
      Tools.ToRadians(0),
      15,
      Vector3.Zero(),
      scene
    );

    // figure creation
    const main = await SceneLoader.ImportMeshAsync(
      "",
      "model/",
      "colored_diamond.glb",
      scene
    );
    const { meshes } = main;
    model = meshes[0];
    model.scaling = new Vector3(4, 4, 4);
    model.alwaysSelectAsActiveMesh = true;
    model.enablePointerMoveEvents = true;
    model.isNearPickable = true;

    // get canvas
    const canvas = scene.getEngine().getRenderingCanvas();

    // camera settings
    camera.allowUpsideDown;
    camera.wheelDeltaPercentage = 0.01;
    camera.lowerRadiusLimit = 8;
    camera.upperRadiusLimit = 70;
    camera.setTarget(model);
    camera.attachControl(canvas, false);

    // lights
    const light = new HemisphericLight("light", new Vector3(0, 20, 20), scene);
    const light2 = new HemisphericLight(
      "light2",
      new Vector3(0, -20, 20),
      scene
    );
    light.intensity = 5.5;
    light2.intensity = 4.5;

    // animation
    const { zoomAnimation, lastZoomFrame } = getZoomAnimation(4);
    scene.beginDirectAnimation(camera, zoomAnimation, 0, lastZoomFrame, false);

    const spin = getSpinAnimation();
    model.animations.push(spin);
    scene.beginAnimation(model, 0, 60, true);
  } catch {}
};

// BABYLON INITIALIZATION
const initBabylonScene = async ({
  antialias,
  engineOptions,
  adaptToDeviceRatio,
  sceneOptions,
  onRender,
  onSceneReady,
  canvas,
}: BabylonjsProps & { canvas: OffscreenCanvas }) => {
  const engine = new Engine(
    canvas,
    antialias,
    engineOptions,
    adaptToDeviceRatio
  );
  const scene = new Scene(engine, sceneOptions);
  try {
    if (scene.isReady()) {
      await onSceneReady(scene);
    } else {
      scene.onReadyObservable.addOnce((scene) => onSceneReady(scene));
    }

    engine.runRenderLoop(() => {
      if (typeof onRender === "function") onRender(scene);
      scene.render();
    });
  } catch {}

  return { scene, canvas };
};

// WORKER EVENT HANDLER
self.onmessage = async ({
  data: { canvas, width, height, dispose, wheel, x, y },
}: MessageEvent<{
  canvas?: OffscreenCanvas;
  width?: number;
  height?: number;
  dispose?: boolean;
  wheel?: number;
  x?: number;
  y?: number;
}>) => {
  try {
    // initialization
    if (canvas) {
      const elements = await initBabylonScene({
        antialias: true,
        onSceneReady,
        canvas: canvas,
      });
      scene = elements.scene;
      offscreenCanvas = elements.canvas;
      self.postMessage("ready");
    }

    // resize
    if (scene && offscreenCanvas && !canvas && width && height) {
      offscreenCanvas.width = width;
      offscreenCanvas.height = height;
      scene.getEngine().resize(true);
    }

    // dispose
    if (dispose && scene) {
      scene.getEngine().dispose();
    }

    // zoom
    if (camera && wheel) {
      camera.radius = camera.radius + wheel * camera.wheelDeltaPercentage;
    }

    // camera rotation
    if (scene && x !== undefined && y !== undefined) {
      camera.alpha -= x / 100;
      camera.beta -= y / 100;
    }
  } catch {}
};
